import React, { useState, useEffect, useRef, useMemo } from "react";

/* ============================================================
   Bearcat Planner
   A gentle daily planner: habits, quests, mood, money, focus.
   Design rules baked in: no red, no daily streaks, no guilt.
   ============================================================ */

const STORE_KEY = "bearcat-planner-v1";

/* ---------- date helpers ---------- */
const dkey = (d = new Date()) => {
  const x = new Date(d);
  return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, "0")}-${String(x.getDate()).padStart(2, "0")}`;
};
const startOfWeek = (d = new Date()) => {
  const x = new Date(d);
  const day = (x.getDay() + 6) % 7; // Monday = 0
  x.setDate(x.getDate() - day);
  x.setHours(0, 0, 0, 0);
  return x;
};
const addDays = (d, n) => {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
};
const weekDays = (base = new Date()) => {
  const s = startOfWeek(base);
  return Array.from({ length: 7 }, (_, i) => dkey(addDays(s, i)));
};
const prettyDate = (d = new Date()) =>
  d.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" });
const uid = () => Math.random().toString(36).slice(2, 9);

/* ---------- seed state ---------- */
const seed = () => ({
  version: 1,
  bearcat: { name: "Mochi", berries: 12, scene: null, owned: [] },
  intentions: {},
  priorities: {},
  moods: {},
  wins: {},
  habits: [
    { id: "h1", name: "Meditate", emoji: "🧘", target: 5 },
    { id: "h2", name: "Workout", emoji: "🏃", target: 4 },
    { id: "h3", name: "Read", emoji: "📖", target: 4 },
    { id: "h4", name: "Walk outside", emoji: "🌿", target: 5 },
  ],
  habitLog: {},
  quests: [
    {
      id: "q1",
      name: "Find a role I'm excited about",
      intention: "I'm someone who reaches out before I feel ready.",
      pinned: true,
      resting: false,
      moves: 0,
      milestones: [
        { id: "m1", text: "Refresh my resume", done: false },
        { id: "m2", text: "Reach out to 5 people", done: false },
        { id: "m3", text: "Tailor 3 applications", done: false },
        { id: "m4", text: "Have 2 real conversations", done: false },
      ],
      evidence: [],
    },
  ],
  money: [],
  sessions: [],
  workouts: [],
  inbox: [],
  reflections: {},
});

/* ---------- storage ---------- */
async function loadState() {
  try {
    const r = await window.storage.get(STORE_KEY);
    if (r && r.value) return { ...seed(), ...JSON.parse(r.value) };
  } catch (e) {
    /* first run, or storage unavailable — start fresh */
  }
  return seed();
}
let saveTimer = null;
function saveState(state) {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(async () => {
    try {
      await window.storage.set(STORE_KEY, JSON.stringify(state));
    } catch (e) {
      /* keep working in memory */
    }
  }, 400);
}

const POSES = {
  happy: "data:image/png;base64,",
  waving: "data:image/png;base64,",
  love: "data:image/png;base64,",
  thumbsup: "data:image/png;base64,",
  sleeping: "data:image/png;base64,",
  reading: "data:image/png;base64,",
  thinking: "data:image/png;base64,",
  exercising: "data:image/png;base64,",
  drink: "data:image/png;base64,",
  playing: "data:image/png;base64,",
  peeking: "data:image/png;base64,",
  sad: "data:image/png;base64,",
  scared: "data:image/png;base64,",
  confused: "data:image/png;base64,",
};

/* ---------- the bearcat ----------
   One artwork. Mood is expressed by what happens AROUND it:
   backdrop tint, motion, sparkles. No sad face, ever.        */
function Bearcat({ mood = "happy", stage = 1, scene = null, size = 150 }) {
  return (
    <div className={`bc-cat bc-mood-${mood}`} style={{ width: size, height: size * 1.071 }}>
      {scene && <span className={`bc-scene bc-scene-${scene}`} />}
      <span className="bc-glow" />
      {stage >= 2 && <span className="bc-halo" />}
      <img src={POSES[mood] || POSES.happy} alt="Mochi the bearcat" draggable="false" />
      {(mood === "love" || mood === "thumbsup") && (
        <span className="bc-pop">
          <i /><i /><i /><i />
        </span>
      )}
      
      {stage >= 3 && (
        <span className="bc-orbit">
          <i /><i /><i />
        </span>
      )}
    </div>
  );
}

/* ---------- small pieces ---------- */
function Card({ title, hint, children, pad = true }) {
  return (
    <section className="bc-card">
      {title && (
        <header className="bc-card-head">
          <h2>{title}</h2>
          {hint && <span className="bc-hint">{hint}</span>}
        </header>
      )}
      <div className={pad ? "bc-card-body" : ""}>{children}</div>
    </section>
  );
}

function Sheet({ open, title, onClose, children }) {
  if (!open) return null;
  return (
    <div className="bc-scrim" onClick={onClose}>
      <div className="bc-sheet" onClick={(e) => e.stopPropagation()}>
        <div className="bc-sheet-grip" />
        <h3>{title}</h3>
        {children}
        <button className="bc-btn bc-btn-ghost bc-w" onClick={onClose}>
          Close
        </button>
      </div>
    </div>
  );
}

const MOOD_ART = ["sad", "scared", "confused", "happy", "love"];
const MOOD_COLORS = ["#CBD8EC", "#D9CDEA", "#F6E3B8", "#F9C2D6", "#F295B8"];
const CATS = ["Food", "Transit", "Home", "Fun", "Health", "Other"];
const SCENES = [
  { id: "blossom", name: "Blossom", cost: 30 },
  { id: "garden", name: "Garden", cost: 60 },
  { id: "night", name: "Night sky", cost: 120 },
  { id: "cafe", name: "Cafe corner", cost: 250 },
];

/* ============================================================
   App
   ============================================================ */
export default function App() {
  const [s, setS] = useState(null);
  const [tab, setTab] = useState("today");
  const [toast, setToast] = useState(null);
  const today = dkey();

  useEffect(() => {
    loadState().then(setS);
  }, []);
  useEffect(() => {
    if (s) saveState(s);
  }, [s]);

  const set = (fn) => setS((prev) => fn({ ...prev }));
  const berries = (n, why) => {
    set((d) => {
      d.bearcat = { ...d.bearcat, berries: d.bearcat.berries + n };
      return d;
    });
    if (why) {
      setToast(`+${n} 🍓 ${why}`);
      setTimeout(() => setToast(null), 1800);
    }
  };

  /* ---- derived: this week's habit progress (drives bearcat mood) ---- */
  const week = weekDays();
  const weekScore = useMemo(() => {
    if (!s || !s.habits.length) return 0;
    let hit = 0;
    let need = 0;
    s.habits.forEach((h) => {
      need += h.target;
      hit += week.filter((d) => s.habitLog[`${h.id}:${d}`]).length;
    });
    return need ? Math.min(1, hit / need) : 0;
  }, [s]);

  const milestonesDone = useMemo(
    () => (s ? s.quests.reduce((n, q) => n + q.milestones.filter((m) => m.done).length, 0) : 0),
    [s]
  );
  const stage = Math.min(3, 1 + Math.floor(milestonesDone / 3));

  const coreDone = s ? !!s.moods[today] && !!s.wins[today] : false;
  const hour = new Date().getHours();
  const nothingYet = s ? !s.moods[today] && !(s.priorities[today] || []).some((x) => x.done) : true;
  const catMood = !s
    ? "peeking"
    : hour >= 21
    ? "sleeping"                              // late: curled up on a pillow
    : hour < 11 && nothingYet
    ? "waving"                                // morning, before you've begun
    : coreDone && weekScore > 0.5
    ? "love"                                  // today done and a good week
    : weekScore > 0.4
    ? "thumbsup"                              // week going well
    : "happy";

  if (!s) {
    return (
      <div className="bc-app">
        <Style />
        <div className="bc-loading">
          <Bearcat mood="peeking" size={120} />
          <p>Waking up your bearcat…</p>
        </div>
      </div>
    );
  }

  return (
    <div className="bc-app">
      <Style />
      <main className="bc-main">
        {tab === "today" && (
          <Today s={s} set={set} berries={berries} catMood={catMood} stage={stage} weekScore={weekScore} />
        )}
        {tab === "habits" && <Habits s={s} set={set} berries={berries} />}
        {tab === "quests" && <Quests s={s} set={set} berries={berries} stage={stage} />}
        {tab === "money" && <Money s={s} set={set} />}
        {tab === "me" && <Me s={s} set={set} stage={stage} catMood={catMood} />}
      </main>

      {toast && <div className="bc-toast">{toast}</div>}

      <nav className="bc-tabs">
        {[
          ["today", "\u{1F3E0}", "Today"],
          ["habits", "\u{1F338}", "Habits"],
          ["quests", "\u{1F5FA}\uFE0F", "Quests"],
          ["money", "\u{1FA99}", "Money"],
          ["me", "\u{1F380}", "Me"],
        ].map(([id, icon, label]) => (
          <button key={id} className={`bc-tab ${tab === id ? "on" : ""}`} onClick={() => setTab(id)}>
            <span className="bc-tab-ico">{icon}</span>
            {label}
          </button>
        ))}
      </nav>
    </div>
  );
}

/* ============================================================
   TODAY
   ============================================================ */
function Today({ s, set, berries, catMood, stage, weekScore }) {
  const today = dkey();
  const [pri, setPri] = useState("");
  const [win, setWin] = useState(s.wins[today] || "");
  const [intent, setIntent] = useState(s.intentions[today] || "");
  const [sheet, setSheet] = useState(null);

  const list = s.priorities[today] || [];
  const pinned = s.quests.find((q) => q.pinned && !q.resting);

  const addPri = () => {
    const t = pri.trim();
    if (!t || list.length >= 3) return;
    set((d) => {
      d.priorities = { ...d.priorities, [today]: [...list, { id: uid(), text: t, done: false }] };
      return d;
    });
    setPri("");
  };
  const togglePri = (id) =>
    set((d) => {
      d.priorities = {
        ...d.priorities,
        [today]: list.map((p) => (p.id === id ? { ...p, done: !p.done } : p)),
      };
      return d;
    });

  const cycleHabit = (h) => {
    const k = `${h.id}:${today}`;
    const cur = s.habitLog[k];
    const cozyThisWeek = weekDays().filter((d) => s.habitLog[`${h.id}:${d}`] === "cozy").length;
    let next;
    if (!cur) next = "done";
    else if (cur === "done") next = cozyThisWeek < 1 ? "cozy" : undefined;
    else next = undefined;
    set((d) => {
      const log = { ...d.habitLog };
      if (next) log[k] = next;
      else delete log[k];
      d.habitLog = log;
      return d;
    });
    if (next === "done") berries(3, h.name);
    if (next === "cozy") berries(1, "rest counts");
  };

  const setMood = (n) => {
    const first = !s.moods[today];
    set((d) => {
      d.moods = { ...d.moods, [today]: n };
      return d;
    });
    if (first) berries(1, "checked in");
  };

  const saveWin = () => {
    const t = win.trim();
    if (!t) return;
    const first = !s.wins[today];
    set((d) => {
      d.wins = { ...d.wins, [today]: t };
      return d;
    });
    if (first) berries(3, "evidence logged");
  };

  return (
    <>
      <div className="bc-hero">
        <Bearcat mood={catMood} stage={stage} scene={s.bearcat.scene} size={168} />
        <div className="bc-hero-meta">
          <p className="bc-eyebrow">{prettyDate()}</p>
          <h1>{s.bearcat.name}</h1>
          <p className="bc-berries">🍓 {s.bearcat.berries} berries</p>
          <div className="bc-ring">
            <div className="bc-ring-fill" style={{ width: `${Math.round(weekScore * 100)}%` }} />
          </div>
          <p className="bc-hint">This week, together</p>
        </div>
      </div>

      <Card title="Today I am…">
        <input
          className="bc-input"
          value={intent}
          placeholder="someone who starts before feeling ready"
          onChange={(e) => setIntent(e.target.value)}
          onBlur={() =>
            set((d) => {
              d.intentions = { ...d.intentions, [today]: intent };
              return d;
            })
          }
        />
      </Card>

      <Card title="How are you?" hint="one tap">
        <div className="bc-moodrow">
          {MOOD_ART.map((k, i) => (
            <button
              key={k}
              className={`bc-mood ${s.moods[today] === i + 1 ? "on" : ""}`}
              style={{ "--m": MOOD_COLORS[i] }}
              onClick={() => setMood(i + 1)}
            >
              <img src={POSES[k]} alt="" />
            </button>
          ))}
        </div>
      </Card>

      <Card title="Three things, at most" hint={`${list.length}/3`}>
        {list.length === 0 && <p className="bc-empty">Pick what would make today feel done.</p>}
        {list.map((p) => (
          <button key={p.id} className={`bc-row ${p.done ? "done" : ""}`} onClick={() => togglePri(p.id)}>
            <span className="bc-check">{p.done ? "✓" : ""}</span>
            {p.text}
          </button>
        ))}
        {list.length < 3 && (
          <div className="bc-addrow">
            <input
              className="bc-input"
              value={pri}
              placeholder="Add one"
              onChange={(e) => setPri(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && addPri()}
            />
            <button className="bc-btn" onClick={addPri}>
              Add
            </button>
          </div>
        )}
        {pinned && (
          <button
            className="bc-nudge"
            onClick={() => {
              const next = pinned.milestones.find((m) => !m.done);
              if (!next || list.length >= 3) return;
              set((d) => {
                d.priorities = {
                  ...d.priorities,
                  [today]: [...list, { id: uid(), text: next.text, done: false }],
                };
                return d;
              });
            }}
          >
            🗺️ One small move on <b>{pinned.name}</b>?
          </button>
        )}
      </Card>

      <Card title="Habits" hint="tap once for done, twice to rest">
        <div className="bc-chips">
          {s.habits.map((h) => {
            const st = s.habitLog[`${h.id}:${today}`];
            return (
              <button key={h.id} className={`bc-chip ${st || ""}`} onClick={() => cycleHabit(h)}>
                <span className="bc-chip-emoji">{h.emoji}</span>
                {h.name}
                {st === "cozy" && <span className="bc-chip-tag">rest</span>}
              </button>
            );
          })}
        </div>
      </Card>

      <Card title="One small win" hint="your evidence">
        <textarea
          className="bc-input bc-area"
          value={win}
          placeholder="Something true about today, however small."
          onChange={(e) => setWin(e.target.value)}
          onBlur={saveWin}
        />
      </Card>

      <Card title="As it happens" hint="only when it happens">
        <div className="bc-quickrow">
          {[
            ["timer", "reading", "Focus"],
            ["meditate", "sleeping", "Breathe"],
            ["workout", "exercising", "Workout"],
            ["money", "drink", "Money"],
            ["inbox", "thinking", "Dump"],
          ].map(([key, art, label]) => (
            <button key={key} className="bc-quick" onClick={() => setSheet(key)}>
              <img src={POSES[art]} alt="" />
              <span>{label}</span>
            </button>
          ))}
        </div>
      </Card>

      <TimerSheet
        open={sheet === "timer" || sheet === "meditate"}
        kind={sheet === "meditate" ? "meditate" : "focus"}
        onClose={() => setSheet(null)}
        set={set}
        berries={berries}
        stage={stage}
        scene={s.bearcat.scene}
      />
      <WorkoutSheet open={sheet === "workout"} onClose={() => setSheet(null)} set={set} berries={berries} />
      <MoneySheet open={sheet === "money"} onClose={() => setSheet(null)} set={set} />
      <InboxSheet open={sheet === "inbox"} onClose={() => setSheet(null)} s={s} set={set} />
    </>
  );
}

/* ---------- timer (focus + meditation share one engine) ---------- */
function TimerSheet({ open, kind, onClose, set, berries, stage, scene }) {
  const OPTS = kind === "meditate" ? [3, 5, 10, 20] : [15, 25, 50];
  const [mins, setMins] = useState(kind === "meditate" ? 5 : 25);
  const [left, setLeft] = useState(null);
  const [tag, setTag] = useState("study");
  const ref = useRef(null);

  useEffect(() => {
    if (left === null) return;
    if (left <= 0) {
      clearInterval(ref.current);
      set((d) => {
        d.sessions = [...d.sessions, { id: uid(), date: dkey(), kind, minutes: mins, tag }];
        return d;
      });
      berries(5, kind === "meditate" ? "stillness" : "focus");
      setLeft(null);
      return;
    }
    ref.current = setInterval(() => setLeft((v) => v - 1), 1000);
    return () => clearInterval(ref.current);
  }, [left]);

  useEffect(() => () => clearInterval(ref.current), []);
  if (!open) return null;

  const mm = left !== null ? String(Math.floor(left / 60)).padStart(2, "0") : String(mins).padStart(2, "0");
  const ss = left !== null ? String(left % 60).padStart(2, "0") : "00";

  return (
    <Sheet open={open} title={kind === "meditate" ? "Breathe together" : "Focus together"} onClose={onClose}>
      <div className={`bc-timerbox ${left !== null ? "running" : ""}`}>
        <Bearcat mood={kind === "meditate" ? "sleeping" : "reading"} stage={stage} scene={scene} size={130} />
        <p className="bc-clock">
          {mm}:{ss}
        </p>
      </div>
      {left === null ? (
        <>
          <div className="bc-chips">
            {OPTS.map((m) => (
              <button key={m} className={`bc-chip ${mins === m ? "done" : ""}`} onClick={() => setMins(m)}>
                {m} min
              </button>
            ))}
          </div>
          {kind === "focus" && (
            <div className="bc-chips">
              {["study", "applications", "admin", "making"].map((t) => (
                <button key={t} className={`bc-chip small ${tag === t ? "done" : ""}`} onClick={() => setTag(t)}>
                  {t}
                </button>
              ))}
            </div>
          )}
          <button className="bc-btn bc-w" onClick={() => setLeft(mins * 60)}>
            Start
          </button>
        </>
      ) : (
        <button className="bc-btn bc-btn-ghost bc-w" onClick={() => setLeft(null)}>
          Stop early — no harm done
        </button>
      )}
    </Sheet>
  );
}

function WorkoutSheet({ open, onClose, set, berries }) {
  const [type, setType] = useState("run");
  const [min, setMin] = useState("30");
  return (
    <Sheet open={open} title="Log a workout" onClose={onClose}>
      <div className="bc-chips">
        {["run", "gym", "yoga", "walk", "other"].map((t) => (
          <button key={t} className={`bc-chip ${type === t ? "done" : ""}`} onClick={() => setType(t)}>
            {t}
          </button>
        ))}
      </div>
      <input
        className="bc-input"
        type="number"
        value={min}
        onChange={(e) => setMin(e.target.value)}
        placeholder="minutes"
      />
      <p className="bc-hint">Minutes and type only. No weight, no calories — effort is the point.</p>
      <button
        className="bc-btn bc-w"
        onClick={() => {
          const m = parseInt(min, 10);
          if (!m) return;
          set((d) => {
            d.workouts = [...d.workouts, { id: uid(), date: dkey(), type, minutes: m }];
            return d;
          });
          berries(5, "moved your body");
          onClose();
        }}
      >
        Log it
      </button>
    </Sheet>
  );
}

function MoneySheet({ open, onClose, set }) {
  const [dir, setDir] = useState("out");
  const [amt, setAmt] = useState("");
  const [cat, setCat] = useState("Food");
  const inCats = ["Shift income", "Other income"];
  const cats = dir === "in" ? inCats : CATS;
  return (
    <Sheet open={open} title="Money" onClose={onClose}>
      <div className="bc-seg">
        <button className={dir === "out" ? "on" : ""} onClick={() => { setDir("out"); setCat("Food"); }}>
          Spent
        </button>
        <button className={dir === "in" ? "on" : ""} onClick={() => { setDir("in"); setCat("Shift income"); }}>
          Earned
        </button>
      </div>
      <input
        className="bc-input bc-amount"
        type="number"
        value={amt}
        placeholder="0.00"
        onChange={(e) => setAmt(e.target.value)}
      />
      <div className="bc-chips">
        {cats.map((c) => (
          <button key={c} className={`bc-chip small ${cat === c ? "done" : ""}`} onClick={() => setCat(c)}>
            {c}
          </button>
        ))}
      </div>
      <button
        className="bc-btn bc-w"
        onClick={() => {
          const v = parseFloat(amt);
          if (!v) return;
          set((d) => {
            d.money = [...d.money, { id: uid(), date: dkey(), amount: v, dir, cat }];
            return d;
          });
          onClose();
          setAmt("");
        }}
      >
        Save
      </button>
    </Sheet>
  );
}

function InboxSheet({ open, onClose, s, set }) {
  const [t, setT] = useState("");
  return (
    <Sheet open={open} title="Brain dump" onClose={onClose}>
      <p className="bc-hint">Park it here so today stays to three things.</p>
      <div className="bc-addrow">
        <input className="bc-input" value={t} placeholder="Anything on your mind" onChange={(e) => setT(e.target.value)} />
        <button
          className="bc-btn"
          onClick={() => {
            if (!t.trim()) return;
            set((d) => {
              d.inbox = [...d.inbox, { id: uid(), text: t.trim() }];
              return d;
            });
            setT("");
          }}
        >
          Add
        </button>
      </div>
      {s.inbox.map((i) => (
        <button
          key={i.id}
          className="bc-row"
          onClick={() =>
            set((d) => {
              d.inbox = d.inbox.filter((x) => x.id !== i.id);
              return d;
            })
          }
        >
          <span className="bc-check" />
          {i.text}
        </button>
      ))}
      {s.inbox.length === 0 && <p className="bc-empty">Empty, which is a good sign.</p>}
    </Sheet>
  );
}

/* ============================================================
   HABITS — weekly targets, decaying streaks, cozy days
   ============================================================ */
function Habits({ s, set, berries }) {
  const [name, setName] = useState("");
  const [emoji, setEmoji] = useState("🌸");
  const [target, setTarget] = useState(4);

  const allMet =
    s.habits.length > 0 &&
    s.habits.every((h) => weekDays().filter((d) => s.habitLog[`${h.id}:${d}`]).length >= h.target);

  const weeksBack = 8;
  const streakOf = (h) => {
    let streak = 0;
    for (let w = weeksBack; w >= 1; w--) {
      const base = addDays(new Date(), -7 * w);
      const days = weekDays(base);
      const hits = days.filter((d) => s.habitLog[`${h.id}:${d}`]).length;
      streak = hits >= h.target ? streak + 1 : Math.max(0, streak - 1);
    }
    return streak;
  };

  return (
    <>
      <div className="bc-pagehead bc-pagehead-cat">
        <div>
          <h1>Habits</h1>
          <p>Weekly targets, not daily chains. A missed Tuesday is invisible.</p>
        </div>
        <Bearcat mood={allMet ? "thumbsup" : "playing"} stage={1} size={78} />
      </div>

      {s.habits.map((h) => {
        const days = weekDays();
        const hits = days.filter((d) => s.habitLog[`${h.id}:${d}`]).length;
        const met = hits >= h.target;
        return (
          <Card key={h.id}>
            <div className="bc-habit-head">
              <span className="bc-chip-emoji big">{h.emoji}</span>
              <div>
                <h3>{h.name}</h3>
                <p className="bc-hint">
                  {hits} of {h.target} this week{met ? " · target met 🍓" : ""}
                </p>
              </div>
              <div className="bc-streak">
                <b>{streakOf(h)}</b>
                <span>wk</span>
              </div>
            </div>
            <div className="bc-weekgrid">
              {days.map((d, i) => {
                const st = s.habitLog[`${h.id}:${d}`];
                const future = d > dkey();
                return (
                  <button
                    key={d}
                    disabled={future}
                    className={`bc-day ${st || ""} ${future ? "future" : ""}`}
                    onClick={() => {
                      const k = `${h.id}:${d}`;
                      const cozy = days.filter((x) => s.habitLog[`${h.id}:${x}`] === "cozy").length;
                      let next;
                      if (!st) next = "done";
                      else if (st === "done") next = cozy < 1 ? "cozy" : undefined;
                      set((dd) => {
                        const log = { ...dd.habitLog };
                        if (next) log[k] = next;
                        else delete log[k];
                        dd.habitLog = log;
                        return dd;
                      });
                      if (next === "done") berries(3, h.name);
                    }}
                  >
                    {["M", "T", "W", "T", "F", "S", "S"][i]}
                  </button>
                );
              })}
            </div>
          </Card>
        );
      })}

      <Card title="Add a habit" hint="four or five is plenty">
        <div className="bc-chips">
          {["🌸", "🧘", "🏃", "📖", "🌿", "💧", "🎧", "🧹"].map((e) => (
            <button key={e} className={`bc-chip ${emoji === e ? "done" : ""}`} onClick={() => setEmoji(e)}>
              {e}
            </button>
          ))}
        </div>
        <input className="bc-input" value={name} placeholder="What habit?" onChange={(e) => setName(e.target.value)} />
        <label className="bc-hint">Target: {target}× per week</label>
        <input
          className="bc-range"
          type="range"
          min="1"
          max="7"
          value={target}
          onChange={(e) => setTarget(+e.target.value)}
        />
        <button
          className="bc-btn bc-w"
          onClick={() => {
            if (!name.trim()) return;
            set((d) => {
              d.habits = [...d.habits, { id: uid(), name: name.trim(), emoji, target }];
              return d;
            });
            setName("");
          }}
        >
          Add habit
        </button>
      </Card>
    </>
  );
}

/* ============================================================
   QUESTS — the long game
   ============================================================ */
function Quests({ s, set, berries, stage }) {
  const [openId, setOpenId] = useState(s.quests[0]?.id || null);
  const [newQ, setNewQ] = useState("");
  const [ev, setEv] = useState("");

  const upd = (qid, fn) =>
    set((d) => {
      d.quests = d.quests.map((q) => (q.id === qid ? fn({ ...q }) : q));
      return d;
    });

  return (
    <>
      <div className="bc-pagehead bc-pagehead-cat">
        <div>
          <h1>Quests</h1>
          <p>The long things. Measured in moves you control, never in outcomes you don't.</p>
        </div>
        <Bearcat mood="thinking" stage={1} size={78} />
      </div>

      {s.quests.map((q) => {
        const done = q.milestones.filter((m) => m.done).length;
        const open = openId === q.id;
        return (
          <Card key={q.id}>
            <button className="bc-questhead" onClick={() => setOpenId(open ? null : q.id)}>
              <div>
                <h3>
                  {q.pinned && "📌 "}
                  {q.name}
                </h3>
                <p className="bc-hint">
                  {done}/{q.milestones.length} milestones · {q.moves} moves made
                  {q.resting && " · resting"}
                </p>
              </div>
              <span className="bc-caret">{open ? "▾" : "▸"}</span>
            </button>

            <QuestPath milestones={q.milestones} stage={stage} scene={s.bearcat.scene} />

            {open && (
              <>
                <div className="bc-intention">
                  <p className="bc-eyebrow">Intention</p>
                  <input
                    className="bc-input bc-italic"
                    defaultValue={q.intention}
                    placeholder="I'm someone who…"
                    onBlur={(e) => upd(q.id, (x) => ({ ...x, intention: e.target.value }))}
                  />
                  <p className="bc-hint">Present tense. Describe who you are, not what you want.</p>
                </div>

                {q.milestones.map((m) => (
                  <button
                    key={m.id}
                    className={`bc-row ${m.done ? "done" : ""}`}
                    onClick={() => {
                      const nowDone = !m.done;
                      upd(q.id, (x) => ({
                        ...x,
                        milestones: x.milestones.map((y) => (y.id === m.id ? { ...y, done: nowDone } : y)),
                        moves: nowDone ? x.moves + 1 : x.moves,
                      }));
                      if (nowDone) berries(25, "milestone!");
                    }}
                  >
                    <span className="bc-check">{m.done ? "✓" : ""}</span>
                    {m.text}
                  </button>
                ))}

                <MilestoneAdd onAdd={(t) => upd(q.id, (x) => ({ ...x, milestones: [...x.milestones, { id: uid(), text: t, done: false }] }))} />

                <div className="bc-evidence">
                  <p className="bc-eyebrow">Evidence</p>
                  {q.evidence.length === 0 && <p className="bc-empty">Proof goes here. Start with one line.</p>}
                  {q.evidence.map((e, i) => (
                    <p key={i} className="bc-ev">
                      <span>{e.date}</span> {e.text}
                    </p>
                  ))}
                  <div className="bc-addrow">
                    <input
                      className="bc-input"
                      value={ev}
                      placeholder="Something I did that proves it"
                      onChange={(e) => setEv(e.target.value)}
                    />
                    <button
                      className="bc-btn"
                      onClick={() => {
                        if (!ev.trim()) return;
                        upd(q.id, (x) => ({
                          ...x,
                          evidence: [{ date: dkey(), text: ev.trim() }, ...x.evidence],
                          moves: x.moves + 1,
                        }));
                        berries(3, "evidence");
                        setEv("");
                      }}
                    >
                      Add
                    </button>
                  </div>
                </div>

                <div className="bc-questfoot">
                  <button className="bc-btn bc-btn-ghost" onClick={() => set((d) => {
                    d.quests = d.quests.map((x) => ({ ...x, pinned: x.id === q.id }));
                    return d;
                  })}>
                    Pin to Today
                  </button>
                  <button className="bc-btn bc-btn-ghost" onClick={() => upd(q.id, (x) => ({ ...x, resting: !x.resting }))}>
                    {q.resting ? "Wake it up" : "Let it rest"}
                  </button>
                </div>
              </>
            )}
          </Card>
        );
      })}

      <Card title="Start a quest">
        <div className="bc-addrow">
          <input className="bc-input" value={newQ} placeholder="What are you growing toward?" onChange={(e) => setNewQ(e.target.value)} />
          <button
            className="bc-btn"
            onClick={() => {
              if (!newQ.trim()) return;
              set((d) => {
                d.quests = [
                  ...d.quests,
                  { id: uid(), name: newQ.trim(), intention: "", pinned: false, resting: false, moves: 0, milestones: [], evidence: [] },
                ];
                return d;
              });
              setNewQ("");
            }}
          >
            Add
          </button>
        </div>
      </Card>
    </>
  );
}

function MilestoneAdd({ onAdd }) {
  const [t, setT] = useState("");
  return (
    <div className="bc-addrow">
      <input
        className="bc-input"
        value={t}
        placeholder="A step you control"
        onChange={(e) => setT(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter" && t.trim()) {
            onAdd(t.trim());
            setT("");
          }
        }}
      />
      <button
        className="bc-btn"
        onClick={() => {
          if (!t.trim()) return;
          onAdd(t.trim());
          setT("");
        }}
      >
        Add
      </button>
    </div>
  );
}

function QuestPath({ milestones, stage, scene }) {
  const n = Math.max(milestones.length, 2);
  const W = 320;
  const H = 120;
  const pts = milestones.map((m, i) => ({
    x: 34 + (i * (W - 68)) / Math.max(n - 1, 1),
    y: 68 + Math.sin(i * 1.25) * 26,
    done: m.done,
  }));
  const d = pts
    .map((p, i) => (i === 0 ? `M${p.x} ${p.y}` : `Q${(pts[i - 1].x + p.x) / 2} ${pts[i - 1].y} ${p.x} ${p.y}`))
    .join(" ");
  const here = [...pts].reverse().find((p) => p.done) || pts[0];

  return (
    <div className="bc-pathwrap">
      <svg viewBox={`0 0 ${W} ${H}`} className="bc-path">
        <path d={d} stroke="var(--path)" strokeWidth="9" fill="none" strokeLinecap="round" strokeDasharray="1 14" />
        {pts.map((p, i) => (
          <g key={i}>
            <circle cx={p.x} cy={p.y} r={p.done ? 11 : 8} fill={p.done ? "var(--pink-deep)" : "var(--path)"} />
            {p.done && (
              <path d={`M${p.x - 4} ${p.y} l3 3.5 5.5 -6`} stroke="#fff" strokeWidth="2.4" fill="none" strokeLinecap="round" />
            )}
          </g>
        ))}
      </svg>
      <div
        className="bc-pathcat"
        style={{ left: `${(here.x / W) * 100}%`, top: `${(here.y / H) * 100}%` }}
      >
        <Bearcat mood="happy" stage={stage} scene={scene} size={46} />
      </div>
    </div>
  );
}

/* ============================================================
   MONEY
   ============================================================ */
function Money({ s }) {
  const [period, setPeriod] = useState(1); // months
  const since = addDays(new Date(), -30 * period);
  const rows = s.money.filter((m) => new Date(m.date) >= since);
  const inSum = rows.filter((r) => r.dir === "in").reduce((a, b) => a + b.amount, 0);
  const outSum = rows.filter((r) => r.dir === "out").reduce((a, b) => a + b.amount, 0);
  const byCat = {};
  rows.filter((r) => r.dir === "out").forEach((r) => (byCat[r.cat] = (byCat[r.cat] || 0) + r.amount));
  const max = Math.max(1, ...Object.values(byCat));

  // mood × spending, the insight a spreadsheet can't give you
  const spendOn = (lo) => {
    const days = Object.keys(s.moods).filter((d) => (lo ? s.moods[d] <= 2 : s.moods[d] >= 4));
    const tot = s.money.filter((m) => m.dir === "out" && days.includes(m.date)).reduce((a, b) => a + b.amount, 0);
    return days.length ? tot / days.length : null;
  };
  const low = spendOn(true);
  const high = spendOn(false);

  return (
    <>
      <div className="bc-pagehead">
        <h1>Money</h1>
        <p>Entered by hand, on purpose. Nothing syncs, nothing leaks.</p>
      </div>

      <div className="bc-seg">
        {[[1, "Month"], [3, "Quarter"], [6, "Half"], [12, "Year"]].map(([v, l]) => (
          <button key={v} className={period === v ? "on" : ""} onClick={() => setPeriod(v)}>
            {l}
          </button>
        ))}
      </div>

      <Card>
        <div className="bc-stats">
          <div>
            <p className="bc-eyebrow">In</p>
            <b className="bc-stat mint">${inSum.toFixed(0)}</b>
          </div>
          <div>
            <p className="bc-eyebrow">Out</p>
            <b className="bc-stat">${outSum.toFixed(0)}</b>
          </div>
          <div>
            <p className="bc-eyebrow">Kept</p>
            <b className="bc-stat pink">${(inSum - outSum).toFixed(0)}</b>
          </div>
        </div>
      </Card>

      <Card title="Where it went">
        {Object.keys(byCat).length === 0 && <p className="bc-empty">Log something from Today and it appears here.</p>}
        {Object.entries(byCat)
          .sort((a, b) => b[1] - a[1])
          .map(([c, v]) => (
            <div key={c} className="bc-bar">
              <span>{c}</span>
              <div className="bc-bar-track">
                <div className="bc-bar-fill" style={{ width: `${(v / max) * 100}%` }} />
              </div>
              <b>${v.toFixed(0)}</b>
            </div>
          ))}
      </Card>

      {low !== null && high !== null && (
        <Card title="A pattern">
          <p className="bc-insight">
            On low-mood days you spend about <b>${low.toFixed(0)}</b>. On good days, <b>${high.toFixed(0)}</b>.
            {low > high * 1.2 ? " Worth noticing." : " Nicely steady."}
          </p>
        </Card>
      )}
    </>
  );
}

/* ============================================================
   ME — year in pixels, minutes, shop, reflection
   ============================================================ */
function Me({ s, set, stage, catMood }) {
  const year = new Date().getFullYear();
  const jan1 = new Date(year, 0, 1);
  const cells = Array.from({ length: 371 }, (_, i) => {
    const d = addDays(startOfWeek(jan1), i);
    return { key: dkey(d), inYear: d.getFullYear() === year };
  });

  const mins = (kind) => s.sessions.filter((x) => x.kind === kind).reduce((a, b) => a + b.minutes, 0);
  const workoutMins = s.workouts.reduce((a, b) => a + b.minutes, 0);

  const wk = dkey(startOfWeek());
  const refl = s.reflections[wk] || {};
  const setRefl = (k, v) =>
    set((d) => {
      d.reflections = { ...d.reflections, [wk]: { ...refl, [k]: v } };
      return d;
    });

  const buy = (o) => {
    if (s.bearcat.berries < o.cost) return;
    set((d) => {
      d.bearcat = {
        ...d.bearcat,
        berries: d.bearcat.berries - o.cost,
        owned: [...d.bearcat.owned, o.id],
        scene: o.id,
      };
      return d;
    });
  };

  return (
    <>
      <div className="bc-pagehead">
        <h1>Me</h1>
        <p>A year of you, at a glance.</p>
      </div>

      <Card title="Year in pixels" hint="one square, one day">
        <div className="bc-pixels">
          {cells.map((c) => {
            const m = s.moods[c.key];
            return (
              <i
                key={c.key}
                title={c.key}
                style={{
                  background: m ? MOOD_COLORS[m - 1] : "var(--pixel)",
                  opacity: c.inYear ? 1 : 0.25,
                }}
              />
            );
          })}
        </div>
        <div className="bc-legend">
          {MOOD_COLORS.map((c, i) => (
            <i key={i} style={{ background: c }} />
          ))}
          <span className="bc-hint">low → bright</span>
        </div>
      </Card>

      <Card title="Time you've given yourself">
        <div className="bc-stats">
          <div>
            <p className="bc-eyebrow">Focus</p>
            <b className="bc-stat">{mins("focus")}m</b>
          </div>
          <div>
            <p className="bc-eyebrow">Breathing</p>
            <b className="bc-stat lilac">{mins("meditate")}m</b>
          </div>
          <div>
            <p className="bc-eyebrow">Moving</p>
            <b className="bc-stat mint">{workoutMins}m</b>
          </div>
        </div>
      </Card>

      <Card title="Sunday reflection" hint="once a week is enough">
        {[
          ["proud", "What am I proud of?"],
          ["learned", "What did I learn about myself?"],
          ["next", "What's one thing for next week?"],
        ].map(([k, q]) => (
          <div key={k} className="bc-reflect">
            <label>{q}</label>
            <textarea className="bc-input bc-area" defaultValue={refl[k] || ""} onBlur={(e) => setRefl(k, e.target.value)} />
          </div>
        ))}
      </Card>

      <Card title={`${s.bearcat.name}'s corner`} hint={`🍓 ${s.bearcat.berries}`}>
        <div className="bc-shopcat">
          <Bearcat mood={catMood} stage={stage} scene={s.bearcat.scene} size={140} />
          <p className="bc-hint">
            Stage {stage} of 3 — grows with quest milestones, not streaks.
          </p>
        </div>
        <div className="bc-chips">
          {SCENES.map((o) => {
            const owned = s.bearcat.owned.includes(o.id);
            return (
              <button
                key={o.id}
                className={`bc-chip ${s.bearcat.scene === o.id ? "done" : ""}`}
                onClick={() =>
                  owned
                    ? set((d) => {
                        d.bearcat = { ...d.bearcat, scene: d.bearcat.scene === o.id ? null : o.id };
                        return d;
                      })
                    : buy(o)
                }
              >
                {o.name} {owned ? "" : `· 🍓${o.cost}`}
              </button>
            );
          })}
        </div>
      </Card>

      <Card title="Watch data" hint="optional">
        <p className="bc-hint">
          Paste a line from your Apple Shortcut, e.g. <code>steps 8400, sleep 7.2, workout 45 run</code>. Nothing is
          sent anywhere.
        </p>
        <PasteBox set={set} />
      </Card>
    </>
  );
}

function PasteBox({ set }) {
  const [t, setT] = useState("");
  const [msg, setMsg] = useState("");
  return (
    <>
      <input className="bc-input" value={t} placeholder="paste here" onChange={(e) => setT(e.target.value)} />
      <button
        className="bc-btn bc-w"
        onClick={() => {
          const m = t.match(/workout\s+(\d+)\s*([a-z]+)?/i);
          if (m) {
            set((d) => {
              d.workouts = [...d.workouts, { id: uid(), date: dkey(), type: m[2] || "other", minutes: +m[1] }];
              return d;
            });
            setMsg(`Logged ${m[1]} min ${m[2] || "workout"}.`);
            setT("");
          } else {
            setMsg("Couldn't find a workout in that. Try: workout 45 run");
          }
        }}
      >
        Import
      </button>
      {msg && <p className="bc-hint">{msg}</p>}
    </>
  );
}

/* ============================================================
   Styles
   ============================================================ */
function Style() {
  return (
    <style>{`
@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;700&family=Nunito:wght@400;600;700&display=swap');

.bc-app{
  /* Pantone spec */
  --pink:#EA96B4;        /* 2333 C  body        */
  --pink-pale:#F8CEDE;   /* 2331 U  belly/snout */
  --pink-deep:#EA768E;   /* 701 C   ears/pads   */
  --ink:#5A285A;         /* 2627 C  eyes/text   */
  --line:#230F23;        /* Neutral Black C     */
  --blush:#F08080;       /* 7416 C              */
  /* supporting */
  --bg:#FFF4F8; --card:#FFFFFF; --cream:#FFF8F3;
  --lilac:#C9B6E4; --mint:#A8DCC6; --butter:#F9E1A8;
  --ink-soft:#A184A1; --path:#F6DCE7; --pixel:#F7E6EE;
  --radius:22px;
  background:var(--bg); color:var(--ink);
  font-family:'Nunito',ui-rounded,'Avenir Next',system-ui,sans-serif;
  min-height:100vh; padding:14px 14px 96px; box-sizing:border-box;
  max-width:520px; margin:0 auto;
}
.bc-app *{box-sizing:border-box}
.bc-app h1,.bc-app h2,.bc-app h3{font-family:'Baloo 2',ui-rounded,system-ui,sans-serif;font-weight:700;margin:0;letter-spacing:.2px}
.bc-app h1{font-size:26px}
.bc-app h2{font-size:16px}
.bc-app h3{font-size:17px}
.bc-app p{margin:0}
.bc-loading{display:grid;place-items:center;gap:10px;min-height:70vh;color:var(--ink-soft)}

.bc-eyebrow{font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-soft);font-weight:700}
.bc-hint{font-size:12.5px;color:var(--ink-soft)}
.bc-empty{font-size:13.5px;color:var(--ink-soft);padding:6px 0}

.bc-hero{display:flex;align-items:center;gap:6px;margin:2px 0 16px}
.bc-hero-meta{flex:1;min-width:0}
.bc-berries{font-size:13px;color:var(--pink-deep);font-weight:700;margin-top:2px}
.bc-ring{height:10px;border-radius:99px;background:var(--pink-pale);margin:10px 0 4px;overflow:hidden}
.bc-ring-fill{height:100%;border-radius:99px;background:linear-gradient(90deg,var(--lilac),var(--pink),var(--pink-deep));transition:width .5s cubic-bezier(.3,1.4,.4,1)}

.bc-pagehead{padding:6px 4px 14px}
.bc-pagehead p{font-size:13.5px;color:var(--ink-soft);margin-top:4px;max-width:38ch}

.bc-card{background:var(--card);border-radius:var(--radius);padding:15px;margin-bottom:12px;box-shadow:0 5px 18px rgba(228,119,159,.09)}
.bc-card-head{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin-bottom:10px}
.bc-card-body{display:flex;flex-direction:column;gap:9px}

.bc-input{width:100%;border:1.5px solid var(--pink-pale);background:#FFFBFD;border-radius:14px;padding:11px 13px;font:inherit;font-size:15px;color:var(--ink);outline:none}
.bc-input:focus{border-color:var(--pink);box-shadow:0 0 0 3px rgba(247,168,196,.28)}
.bc-input::placeholder{color:#D3BECA}
.bc-area{min-height:62px;resize:vertical}
.bc-italic{font-style:italic}
.bc-amount{font-size:26px;font-weight:700;text-align:center;font-family:'Baloo 2',sans-serif}
.bc-range{width:100%;accent-color:var(--pink-deep)}

.bc-btn{border:none;background:var(--pink-deep);color:#fff;font:inherit;font-weight:700;font-size:14.5px;padding:11px 17px;border-radius:14px;cursor:pointer;transition:transform .12s}
.bc-btn:active{transform:scale(.96)}
.bc-btn-ghost{background:#FBE9F0;color:var(--pink-deep)}
.bc-w{width:100%;margin-top:4px}

.bc-addrow{display:flex;gap:8px}
.bc-addrow .bc-input{flex:1}

.bc-row{display:flex;align-items:center;gap:11px;width:100%;text-align:left;background:#FFFBFD;border:1.5px solid var(--pink-pale);border-radius:14px;padding:12px 13px;font:inherit;font-size:15px;color:var(--ink);cursor:pointer}
.bc-row.done{color:var(--ink-soft);text-decoration:line-through;background:#FDF5F8}
.bc-check{width:21px;height:21px;flex:0 0 21px;border-radius:50%;border:2px solid var(--pink);display:grid;place-items:center;color:#fff;font-size:12px;font-weight:800}
.bc-row.done .bc-check{background:var(--pink-deep);border-color:var(--pink-deep)}

.bc-nudge{margin-top:4px;width:100%;text-align:left;background:linear-gradient(100deg,#F7EDFB,#FDEEF5);border:1.5px dashed var(--lilac);color:var(--ink);border-radius:14px;padding:11px 13px;font:inherit;font-size:13.5px;cursor:pointer}

.bc-moodrow{display:flex;gap:8px;justify-content:space-between}
.bc-mood{flex:1;aspect-ratio:1;border:none;border-radius:16px;background:#FDF3F7;cursor:pointer;
  transition:transform .18s cubic-bezier(.3,1.4,.4,1);padding:2px;overflow:hidden}
.bc-mood img{width:100%;height:100%;object-fit:contain;display:block;filter:saturate(.85);opacity:.62;transition:.2s}
.bc-mood.on img{filter:none;opacity:1}
.bc-mood.on{background:var(--m);transform:translateY(-3px) scale(1.06);box-shadow:0 6px 14px rgba(228,119,159,.22)}

.bc-chips{display:flex;flex-wrap:wrap;gap:8px}
.bc-chip{display:inline-flex;align-items:center;gap:7px;border:1.5px solid var(--pink-pale);background:#FFFBFD;border-radius:99px;padding:9px 14px;font:inherit;font-size:14px;font-weight:600;color:var(--ink);cursor:pointer;transition:transform .12s}
.bc-chip.small{font-size:12.5px;padding:7px 12px}
.bc-chip:active{transform:scale(.95)}
.bc-chip.done{background:var(--pink);border-color:var(--pink-deep);color:#fff}
.bc-chip.cozy{background:var(--lilac);border-color:var(--lilac);color:#fff}
.bc-chip-emoji{font-size:16px}
.bc-chip-emoji.big{font-size:26px}
.bc-chip-tag{font-size:10px;letter-spacing:.08em;text-transform:uppercase;opacity:.85}

.bc-quickrow{display:flex;gap:8px;overflow-x:auto;padding-bottom:2px}
.bc-quick{flex:0 0 auto;display:grid;place-items:center;gap:0;width:70px;padding:6px 0 8px;border:none;border-radius:18px;background:#FDF2F7;font:inherit;cursor:pointer}
.bc-quick img{width:42px;height:42px;object-fit:contain;display:block}
.bc-quick span{font-size:11px;font-weight:700;color:var(--ink-soft)}

.bc-habit-head{display:flex;align-items:center;gap:11px;margin-bottom:11px}
.bc-habit-head div{flex:1;min-width:0}
.bc-streak{text-align:center;background:#FDF2F7;border-radius:14px;padding:6px 11px}
.bc-streak b{display:block;font-family:'Baloo 2',sans-serif;font-size:19px;color:var(--pink-deep);line-height:1}
.bc-streak span{font-size:10px;color:var(--ink-soft);font-weight:700}

.bc-weekgrid{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}
.bc-day{aspect-ratio:1;border:2px dotted var(--pink-pale);background:#FFFBFD;border-radius:12px;font:inherit;font-size:11.5px;font-weight:700;color:#CDB6C3;cursor:pointer}
.bc-day.done{background:var(--pink);border:2px solid var(--pink-deep);color:#fff}
.bc-day.cozy{background:var(--lilac);border:2px solid var(--lilac);color:#fff}
.bc-day.future{opacity:.4;cursor:default}

.bc-questhead{display:flex;align-items:center;gap:10px;width:100%;background:none;border:none;padding:0 0 8px;font:inherit;text-align:left;color:var(--ink);cursor:pointer}
.bc-questhead div{flex:1;min-width:0}
.bc-caret{color:var(--pink-deep);font-size:14px}
.bc-path{width:100%;height:auto;display:block;margin:2px 0 10px}
.bc-intention{background:#FBF4FB;border-radius:16px;padding:12px;display:flex;flex-direction:column;gap:7px;margin-bottom:10px}
.bc-evidence{margin-top:12px;display:flex;flex-direction:column;gap:7px}
.bc-ev{font-size:13.5px;padding:9px 11px;background:#FFF9FB;border-left:3px solid var(--pink);border-radius:0 10px 10px 0}
.bc-ev span{color:var(--ink-soft);font-size:11px;font-weight:700;margin-right:6px}
.bc-questfoot{display:flex;gap:8px;margin-top:12px}
.bc-questfoot .bc-btn{flex:1}

.bc-seg{display:flex;background:#FBE9F0;border-radius:14px;padding:4px;gap:4px;margin-bottom:12px}
.bc-seg button{flex:1;border:none;background:none;font:inherit;font-size:13.5px;font-weight:700;color:var(--ink-soft);padding:9px 0;border-radius:11px;cursor:pointer}
.bc-seg button.on{background:#fff;color:var(--pink-deep);box-shadow:0 2px 7px rgba(228,119,159,.16)}

.bc-stats{display:flex;justify-content:space-between;text-align:center;gap:8px}
.bc-stats>div{flex:1}
.bc-stat{font-family:'Baloo 2',sans-serif;font-size:23px;display:block;margin-top:3px}
.bc-stat.mint{color:#5FB595}.bc-stat.pink{color:var(--pink-deep)}.bc-stat.lilac{color:#9B7FC4}

.bc-bar{display:flex;align-items:center;gap:9px;font-size:13.5px}
.bc-bar>span{width:74px;flex:0 0 74px;color:var(--ink-soft);font-weight:600}
.bc-bar-track{flex:1;height:12px;background:#FBEEF3;border-radius:99px;overflow:hidden}
.bc-bar-fill{height:100%;background:linear-gradient(90deg,var(--pink),var(--pink-deep));border-radius:99px}
.bc-bar b{width:46px;text-align:right;font-family:'Baloo 2',sans-serif;font-size:14px}
.bc-insight{font-size:14px;line-height:1.55}

.bc-pixels{display:grid;grid-template-columns:repeat(53,1fr);grid-auto-flow:column;grid-template-rows:repeat(7,1fr);gap:2px}
.bc-pixels i{aspect-ratio:1;border-radius:2px;display:block}
.bc-legend{display:flex;align-items:center;gap:4px;margin-top:9px}
.bc-legend i{width:13px;height:13px;border-radius:3px}
.bc-legend .bc-hint{margin-left:5px}

.bc-reflect{display:flex;flex-direction:column;gap:5px}
.bc-reflect label{font-size:13px;font-weight:700;color:var(--ink-soft)}
.bc-shopcat{display:grid;place-items:center;gap:4px;margin-bottom:11px;text-align:center}

.bc-scrim{position:fixed;inset:0;background:rgba(90,68,83,.34);backdrop-filter:blur(3px);display:flex;align-items:flex-end;justify-content:center;z-index:40}
.bc-sheet{background:var(--bg);border-radius:26px 26px 0 0;padding:10px 17px 22px;width:100%;max-width:520px;max-height:88vh;overflow-y:auto;display:flex;flex-direction:column;gap:11px;animation:bc-up .28s cubic-bezier(.2,1.1,.3,1)}
.bc-sheet-grip{width:44px;height:5px;border-radius:99px;background:#EFD7E3;margin:2px auto 6px}
.bc-sheet h3{font-size:19px;text-align:center;margin-bottom:2px}
@keyframes bc-up{from{transform:translateY(28px);opacity:.4}to{transform:none;opacity:1}}

.bc-timerbox{display:grid;place-items:center}
.bc-clock{font-family:'Baloo 2',sans-serif;font-size:42px;color:var(--pink-deep);line-height:1;margin-top:-6px}
.bc-timerbox.running .bc-cat{animation:bc-breathe 4.5s ease-in-out infinite}
@keyframes bc-breathe{0%,100%{transform:scale(1)}50%{transform:scale(1.05)}}

.bc-toast{position:fixed;left:50%;bottom:88px;transform:translateX(-50%);background:var(--ink);color:#fff;font-size:13.5px;font-weight:700;padding:10px 17px;border-radius:99px;z-index:50;animation:bc-up .3s}

.bc-tabs{position:fixed;bottom:0;left:0;right:0;max-width:520px;margin:0 auto;background:rgba(255,246,250,.95);backdrop-filter:blur(12px);border-top:1px solid #F6E1EB;display:flex;padding:6px 6px 9px;z-index:30}
.bc-tab{flex:1;display:grid;place-items:center;gap:2px;border:none;background:none;font:inherit;font-size:10.5px;font-weight:700;color:var(--ink-soft);padding:2px 0;cursor:pointer;border-radius:14px}
.bc-tab-ico{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;font-size:19px;line-height:1;
  filter:saturate(.55) brightness(1.06);opacity:.6;
  transition:background .25s,opacity .25s,filter .25s,transform .25s cubic-bezier(.3,1.5,.4,1)}
.bc-tab.on{color:var(--pink-deep)}
.bc-tab.on .bc-tab-ico{background:#FBE1EC;opacity:1;filter:saturate(.72) brightness(1.04);transform:translateY(-2px) scale(1.08)}

.bc-cat{position:relative;display:block;margin:0 auto}
.bc-cat img{position:relative;width:100%;height:100%;object-fit:contain;display:block;z-index:2;
  filter:drop-shadow(0 6px 10px rgba(228,119,159,.22))}
.bc-glow{position:absolute;left:50%;top:54%;transform:translate(-50%,-50%);width:96%;aspect-ratio:1;
  border-radius:50%;z-index:0;background:var(--tint);opacity:.55;transition:background .6s,opacity .6s}
.bc-mood-happy{--tint:#FBDCE8}
.bc-mood-waving{--tint:#FAD3E4}
.bc-mood-love{--tint:#FAD0DE}
.bc-mood-thumbsup{--tint:#FBE7C4}
.bc-mood-playing{--tint:#FBE0D6}
.bc-mood-exercising{--tint:#FBDDD2}
.bc-mood-reading{--tint:#E3F0EA}
.bc-mood-thinking{--tint:#FBEFC9}
.bc-mood-drink{--tint:#EDF0DC}
.bc-mood-sleeping{--tint:#E6DFF3}
.bc-mood-peeking{--tint:#FBE4EC}
.bc-mood-sad{--tint:#DCE5F2}
.bc-mood-scared{--tint:#E6E6F2}
.bc-mood-confused{--tint:#EFE7F0}

.bc-mood-waving img{animation:bc-rock 2.6s ease-in-out infinite;transform-origin:50% 92%}
.bc-mood-happy img,.bc-mood-love img,.bc-mood-drink img{animation:bc-idle 3.4s ease-in-out infinite}
.bc-mood-thumbsup img,.bc-mood-exercising img,.bc-mood-playing img{animation:bc-hop 1.2s cubic-bezier(.3,1.5,.4,1) infinite}
.bc-mood-sleeping img{animation:bc-breathe 5.5s ease-in-out infinite}
.bc-mood-reading img,.bc-mood-thinking img{animation:bc-sway 6s ease-in-out infinite;transform-origin:50% 92%}
.bc-mood-peeking img{animation:bc-peek 3.6s ease-in-out infinite}
@keyframes bc-rock{0%,100%{transform:rotate(-3deg) translateY(0)}50%{transform:rotate(3deg) translateY(-3px)}}
@keyframes bc-sway{0%,100%{transform:rotate(-1.6deg)}50%{transform:rotate(1.6deg)}}
@keyframes bc-peek{0%,100%{transform:translateY(5px)}50%{transform:translateY(-2px)}}
.bc-pagehead-cat{display:flex;align-items:flex-end;gap:10px;justify-content:space-between}
.bc-pagehead-cat>div{flex:1;min-width:0}
@keyframes bc-idle{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-4px) rotate(-1.2deg)}}
@keyframes bc-hop{0%,100%{transform:translateY(0) scale(1)}35%{transform:translateY(-11px) scale(1.03)}70%{transform:translateY(0) scale(.98,1.02)}}
@keyframes bc-breathe{0%,100%{transform:scale(1)}50%{transform:scale(1.035)}}

.bc-pop{position:absolute;inset:0;z-index:3;pointer-events:none}
.bc-pop i{position:absolute;width:9px;height:9px;border-radius:2px;animation:bc-confetti 1.7s ease-out infinite}
.bc-pop i:nth-child(1){left:12%;top:26%;background:var(--butter);animation-delay:0s}
.bc-pop i:nth-child(2){right:10%;top:18%;background:var(--lilac);animation-delay:.35s;border-radius:50%}
.bc-pop i:nth-child(3){left:20%;top:8%;background:var(--mint);animation-delay:.7s;border-radius:50%}
.bc-pop i:nth-child(4){right:20%;top:34%;background:var(--pink-deep);animation-delay:1.05s}
@keyframes bc-confetti{0%{transform:translateY(10px) scale(.4) rotate(0);opacity:0}
  30%{opacity:1}100%{transform:translateY(-26px) scale(1) rotate(160deg);opacity:0}}

.bc-orbit{position:absolute;inset:0;z-index:1;animation:bc-spin 18s linear infinite}
.bc-orbit i{position:absolute;width:7px;height:7px;border-radius:50%}
.bc-orbit i:nth-child(1){left:4%;top:38%;background:var(--lilac)}
.bc-orbit i:nth-child(2){right:2%;top:24%;background:var(--butter)}
.bc-orbit i:nth-child(3){left:22%;bottom:8%;background:var(--mint)}

.bc-scene{position:absolute;left:50%;top:54%;transform:translate(-50%,-50%);width:118%;aspect-ratio:1;
  border-radius:50%;z-index:-1;background-repeat:no-repeat}
.bc-scene-blossom{background-color:#FDE4EE;
  background-image:radial-gradient(circle 7px at 18% 22%,#F9C6DC 99%,transparent 100%),
  radial-gradient(circle 5px at 82% 16%,#F9C6DC 99%,transparent 100%),
  radial-gradient(circle 6px at 88% 62%,#F9C6DC 99%,transparent 100%)}
.bc-scene-garden{background-color:#E4F2E9;
  background-image:radial-gradient(circle 8px at 14% 70%,#BEE3CD 99%,transparent 100%),
  radial-gradient(circle 6px at 86% 74%,#BEE3CD 99%,transparent 100%),
  radial-gradient(circle 5px at 50% 8%,#F6E7AE 99%,transparent 100%)}
.bc-scene-night{background-color:#E5DDF6;
  background-image:radial-gradient(circle 3px at 20% 18%,#fff 99%,transparent 100%),
  radial-gradient(circle 2px at 74% 12%,#fff 99%,transparent 100%),
  radial-gradient(circle 3px at 88% 44%,#fff 99%,transparent 100%),
  radial-gradient(circle 2px at 10% 52%,#fff 99%,transparent 100%)}
.bc-scene-cafe{background-color:#FAEBD6;
  background-image:radial-gradient(circle 9px at 16% 24%,#F2D4AE 99%,transparent 100%),
  radial-gradient(circle 7px at 84% 30%,#F2D4AE 99%,transparent 100%)}

.bc-pathwrap{position:relative;margin:2px 0 10px}
.bc-pathcat{position:absolute;transform:translate(-50%,-88%);pointer-events:none}

@media (prefers-reduced-motion:reduce){
  .bc-app *{animation:none!important;transition:none!important}
}
.bc-app button:focus-visible,.bc-app input:focus-visible,.bc-app textarea:focus-visible{outline:3px solid var(--lilac);outline-offset:2px}
`}</style>
  );
}
